 "content": "def transform(grid):
    """Tile the grid 2x2 with clockwise rotations across each quadrant."""
    n = len(grid)
    if n == 0 or any(len(row) != n for row in grid):
        raise ValueError("transform expects a non-empty square grid")

    def rotate_cw(matrix, turns):
        result = [row[:] for row in matrix]
        for _ in range(turns % 4):
            result = [list(row) for row in zip(*result[::-1])]
        return result

    top = [rotate_cw(grid, 0)[r] + rotate_cw(grid, 1)[r] for r in range(n)]
    bottom = [rotate_cw(grid, 3)[r] + rotate_cw(grid, 2)[r] for r in range(n)]
    return top + bottom


